def find_common_elements(set1, *args):
    """
    This function takes in a set and one or more optional sets, and returns a new set containing only the elements that are common to all the sets.
    """

### Solution:


    common_elements = set1.copy()  # Initialize common elements set with the first set

    # Iterate through the optional sets
    for s in args:
        common_elements = common_elements.intersection(s)  # Update common elements set with the intersection of the current set and the previous common elements set

